218→        const model = def.model && VALID_AGENT_MODELS.has(def.model)
219→          ? (def.model as AgentDefinition["model"])
220→          : "inherit";
221→        sdkAgents[name] = {
222→          description: def.description,
223→          prompt: def.prompt,
224→          ...(def.tools ? { tools: def.tools } : {}),
225→          model,
226→        };
227→      }
228→    }
229→
230→    // Common SDK options (without resume/prompt — those vary on retry)
231→    const baseOptions = {
232→      model: modelName,
233→      systemPrompt: body.system_prompt,
234→      allowedTools: ["Skill", "Task", "mcp__duckdb-data-agent__execute_sql", "mcp__duckdb-data-agent__ask_user_question", "mcp__duckdb-data-agent__render_chart"] as string[],
235→      settingSources: ["project"] as SettingSource[],
236→      plugins: [],
237→      hooks: { PreToolUse: [skillAllowlistHook] },
238→      permissionMode: "bypassPermissions" as const,
239→      allowDangerouslySkipPermissions: true,
240→      maxTurns: 20,
241→      includePartialMessages: true,
242→      abortController,
243→      env: sdkEnv,
244→      stderr: (line: string) => {
245→        stderrLines.push(line);
246→        console.error(`[sidecar:cli] ${line}`);
247→      },
248→      ...(sdkAgents ? { agents: sdkAgents } : {}),
249→      ...(body.mcp_server_url
250→        ? {
251→            mcpServers: {
252→              "duckdb-data-agent": {
253→                type: "sse" as const,
254→                url: body.mcp_server_url,
255→              },
256→            },
257→          }
258→        : {}),
259→    };
