261→    // Resume fallback: try with resume first. If the SDK yields a "result"
262→    // message with "No conversation found" (container was recreated and lost
263→    // the session), suppress that error and retry without resume, prepending
264→    // conversation history so the model has context.
265→    let currentPrompt = body.message;
266→    let useResume = !!body.session_id;
267→    let retried = false;
