289→      try {
290→        for await (const message of sdkQuery) {
291→          // Reset idle timer on every message
292→          if (idleTimer) { clearTimeout(idleTimer); }
293→          idleTimer = setTimeout(() => {
294→            console.error(`[sidecar] SDK idle timeout (${SDK_IDLE_TIMEOUT_MS}ms) reached, aborting reqId=${requestId}`);
