299→
300→          // Intercept "No conversation found" result before forwarding
301→          if (useResume && !retried) {
302→            const msg = message as Record<string, unknown>;
303→            if (msg.type === "result" && msg.is_error) {
304→              const resultText = String(msg.result || "");
