342→            const usage =
343→              currentGenUsage.input !== undefined
344→                ? {
345→                    input: currentGenUsage.input || 0,
346→                    output: currentGenUsage.output || 0,
347→                    total: (currentGenUsage.input || 0) + (currentGenUsage.output || 0),
348→                    unit: "TOKENS" as const,
349→                  }
350→                : undefined;
351→            const gen = trace.generation({
352→              name: "claude.assistant.turn",
353→              model: (msgObj.model as string) || modelName,
354→              input: { messages: accumulatedMessages.slice(-6) },
355→              output: { content, role: "assistant" },
356→              usage,
357→            });
358→            gen.end();
359→            currentGenUsage = {};
360→            accumulatedMessages.push({ role: "assistant", content });
361→          } else if (msg.type === "user") {
362→            const msgObj = (msg.message as Record<string, unknown>) || {};
363→            accumulatedMessages.push({ role: "user", content: msgObj.content });
364→          } else if (msg.type === "result") {
365→            const actualSessionId = (msg.session_id as string | undefined) || body.session_id;
366→            const traceSessionId = body.langfuse_session_id || actualSessionId;
367→            trace.update({
368→              ...(traceSessionId ? { sessionId: traceSessionId } : {}),
369→              output: { session_id: actualSessionId },
370→            });
371→          } else if (msg.type === "system") {
372→            const sessionId = msg.session_id as string | undefined;
373→            if (sessionId && !body.langfuse_session_id) {
374→              trace.update({ sessionId });
375→            }
376→          }
377→        } // end for-await
378→      } catch (innerErr: unknown) {
379→        // If we're retrying due to resume failure, swallow the cleanup error
380→        // (e.g., "Claude Code process exited with code 1" after session not found)
381→        if (resumeFailedNeedsRetry) {
382→          console.log(`[sidecar] Swallowing post-resume error during retry: ${innerErr instanceof Error ? innerErr.message : String(innerErr)}`);
383→        } else {
384→          throw innerErr;
385→        }
386→      }
387→
388→      if (resumeFailedNeedsRetry && !retried) {
389→        retried = true;
390→        useResume = false;
391→        let messageWithHistory = "Previous conversation (for context):\n";
392→        for (const entry of body.conversation_history!) {
393→          const role = (entry.role || "user").charAt(0).toUpperCase() + (entry.role || "user").slice(1);
394→          messageWithHistory += `\n${role}: ${entry.content}\n`;
395→        }
396→        messageWithHistory += `\n---\n\nMy new message:\n${body.message}`;
397→        currentPrompt = messageWithHistory;
398→        stderrLines.length = 0;
399→        if (idleTimer) { clearTimeout(idleTimer); idleTimer = null; }
400→        continue; // retry the queryLoop
401→      }
402→
403→      break; // success or non-retryable error — exit queryLoop
404→    } // end queryLoop
405→  } catch (err: unknown) {
406→    let errMsg = err instanceof Error ? err.message : String(err);
407→    // Append CLI stderr for context when the process crashes
408→    if (stderrLines.length > 0) {
409→      errMsg += ` | CLI stderr: ${stderrLines.slice(-5).join(" ")}`;
410→    }
411→    // Don't log abort errors — they are expected on client disconnect
412→    if (!(err instanceof Error && err.name === "AbortError")) {
413→      console.error(`[sidecar] SDK error: ${errMsg}`);
414→      if (!responseEnded) {
415→        res.write(
416→          `data: ${JSON.stringify({ type: "error", message: errMsg })}\n\n`
417→        );
418→      }
419→      if (trace) {
420→        trace.update({ output: { error: errMsg } });
421→      }
422→    }
423→  } finally {
424→    if (idleTimer) { clearTimeout(idleTimer); }
425→    activeAborts.delete(requestId);
426→    responseEnded = true;
427→    res.end();
428→    // Flush Langfuse events before the response is fully closed
429→    if (langfuse) {
430→      await langfuse.flushAsync().catch(() => {});
431→    }
432→    console.log(`[sidecar] SSE stream ended reqId=${requestId}`);
433→  }
434→});
435→
436→app.post("/stop", (_req: Request, res: Response) => {
437→  if (activeAborts.size > 0) {
438→    for (const [id, controller] of activeAborts) {
439→      controller.abort();
440→      activeAborts.delete(id);
441→    }
442→    res.json({ status: "stopped" });
443→  } else {
444→    res.json({ status: "no_active_session" });
445→  }
446→});
447→
448→app.listen(PORT, "0.0.0.0", () => {
449→  console.log(`Sidecar agent server listening on port ${PORT}`);
450→});
